/* Which bits of a pad register are the function selector: the low nibble, on
 * every HiSilicon and Goke part. Named and placed here rather than inlined
 * because three callers used to disagree about it -- one matched vendor
 * strings, one open-coded 0xf and one zeroed the top half of the register. */
static uint32_t padmux_func_mask(void) { return 0xf; }

static const muxctrl_reg_t **regs_by_chip() {
    switch (chip_generation) {
#ifdef IPCHW_PADMUX_V1
    case HISI_V1:
        return CV100regs;
#endif
#ifdef IPCHW_PADMUX_V2A
    case HISI_V2A:
        return AV100regs;
#endif
#ifdef IPCHW_PADMUX_V2
    case HISI_V2:
        if (IS_CHIP("3516CV200"))
            return CV200regs;
        else
            return EV20Xregs;
#endif
#ifdef IPCHW_PADMUX_V3A
    case HISI_V3A:
        return AV200regs;
#endif
#ifdef IPCHW_PADMUX_V3
    case HISI_V3:
        return CV300regs;
#endif
#ifdef IPCHW_PADMUX_V4A
    case HISI_V4A:
        if (IS_CHIP("3516CV500"))
            return CV500regs;
        else
            return DV300regs;
#endif
#ifdef IPCHW_PADMUX_V4
    case HISI_V4:
        if (IS_16EV200)
            return EV200regs;
        else if (IS_16EV300)
            return EV300regs;
        else if (IS_18EV300)
            return _8EV300regs;
        else if (IS_16DV200)
            return DV200regs;
        else if (IS_7205V500)
            return EV200regs;
        break;
#endif
#ifdef IPCHW_PADMUX_V5
    case HISI_OT:
        if (IS_CHIP("3519DV500") || IS_CHIP("3516DV500"))
            return DV500regs;
        return CV610regs;
#endif
#ifdef IPCHW_PADMUX_3536C
    case HISI_3536C:
        return RCV100regs;
#endif
#ifdef IPCHW_PADMUX_3536D
    case HISI_3536D:
        return DV100regs;
#endif
    }

    /* No table for this SoC, or none compiled into this build. NULL rather
     * than exit(): this is reached from a library that a long-lived daemon
     * links, where a missing table is a question to answer, not an outage. */
    return NULL;
}

/* ------------------------------------------------------------------------
 * The HiSilicon and Goke backend.
 *
 * One register per pad, a selector field in the low nibble, and funcs[] above
 * indexed by the value in it. That is the shape the whole API was drawn
 * around, and it is the only one of the three vendors that has it -- see
 * src/padmux.h for what the other two do instead and for the seam this plugs
 * into. The contract a caller sees is on the prototypes in include/ipchw.h.
 *
 * Not one table row moved to get here.
 * ---------------------------------------------------------------------- */

/* "GPIO5_2" -> 42, the running-integer form every consumer of this speaks:
 * eight pads to a bank. -1 for anything that is not a GPIO name. Every GPIO
 * name in every table here is GPIO<bank>_<0..7>; a malformed one would be a
 * data bug, and is reported as "not a GPIO" rather than guessed at. */
static int gpio_name_to_pad(const char *name) {
    if (strncmp(name, "GPIO", 4) != 0)
        return -1;

    int bank, pin;
    if (sscanf(name + 4, "%d_%d", &bank, &pin) != 2)
        return -1;
    if (bank < 0 || pin < 0 || pin > 7)
        return -1;

    return bank * 8 + pin;
}

/* The name of a row's i'th function.
 *
 * A row holds offsets into padmux_names rather than pointers -- see
 * reginfo.h for the relocation arithmetic that bought -- while every caller
 * and every ipchw_padmux_t field speaks `const char *`. This is where the
 * two meet, and it is the only place that knows the difference. */
static const char *row_name(const muxctrl_reg_t *reg, int i) {
    return padmux_name(reg->funcs[i]);
}

/* The GPIO alternative of one row, if it has one. Filled in on every result
 * so a caller holding a PWM row already knows the pad it is taking away and
 * the selector value that hands it back. */
static void row_gpio(const muxctrl_reg_t *reg, const char **name, int *pad,
                     int *func) {
    *name = NULL;
    *pad = -1;
    *func = -1;

    for (int i = 0; reg->funcs[i]; i++) {
        int p = gpio_name_to_pad(row_name(reg, i));
        if (p >= 0) {
            *name = row_name(reg, i);
            *pad = p;
            *func = i;
            return;
        }
    }
}

/* `match` decides which functions of a row are wanted (NULL means every one
 * of them) and `pad` optionally narrows to the rows that carry that GPIO (-1
 * means every row).
 *
 * Both filters live here rather than in a post-pass over the results because
 * a whole table is far more rows than any caller wants to hold: the EV300
 * family alone has some three hundred functions across ninety-three pads.
 *
 * Counting continues past `max` on purpose: the return value is the number of
 * matches, not the number written, so a caller that guessed its array too
 * small learns the right size instead of silently losing rows. */
static int hisi_walk(padmux_match_fn match, const void *arg, int pad,
                     ipchw_padmux_t *out, int max) {
    const muxctrl_reg_t **regs = regs_by_chip();
    if (regs == NULL)
        return IPCHW_PADMUX_NO_TABLE;

    const uint32_t mask = padmux_func_mask();
    int found = 0;

    for (int reg_num = 0; regs[reg_num]; reg_num++) {
        const muxctrl_reg_t *reg = regs[reg_num];
        const char *gpio_name;
        int gpio_pad, gpio_func;

        row_gpio(reg, &gpio_name, &gpio_pad, &gpio_func);
        if (pad >= 0 && gpio_pad != pad)
            continue;

        for (int i = 0; reg->funcs[i]; i++) {
            /* A pad with no function wired to that selector value. Never a
             * thing to mux to, so never a match. */
            if (!strcmp(row_name(reg, i), "reserved"))
                continue;
            if (match != NULL && !match(row_name(reg, i), arg))
                continue;

            if (found < max) {
                out[found] = (ipchw_padmux_t){
                    .address = reg->address,
                    .func_mask = mask,
                    .func = i,
                    .func_name = row_name(reg, i),
                    .gpio_name = gpio_name,
                    .gpio_pad = gpio_pad,
                    .gpio_func = gpio_func,
                    /* One register, one field, every alternative of the pad
                     * in it: the two strongest promises the API can make, and
                     * only this vendor can make them. */
                    .flags = IPCHW_PADMUX_F_RMW | IPCHW_PADMUX_F_SHARED_REG |
                             (i == gpio_func ? IPCHW_PADMUX_F_GPIO : 0),
                };
            }
            found++;
        }
    }

    return found;
}

/* The one register of `pad`, plus the GPIO facts derived from it. NULL when
 * this SoC has no such pad -- which on these parts also means "no table",
 * because a pad the table does not name is a pad this build cannot reach. */
static const muxctrl_reg_t *hisi_pad_reg(int pad, const char **gpio_name,
                                         int *gpio_pad, int *gpio_func) {
    const muxctrl_reg_t **regs = regs_by_chip();
    if (regs == NULL)
        return NULL;

    for (int reg_num = 0; regs[reg_num]; reg_num++) {
        row_gpio(regs[reg_num], gpio_name, gpio_pad, gpio_func);
        if (*gpio_pad == pad)
            return regs[reg_num];
    }

    return NULL;
}

static int hisi_get(int pad, ipchw_padmux_t *out, const padmux_io_t *io) {
    const char *gpio_name;
    int gpio_pad, gpio_func;

    if (regs_by_chip() == NULL)
        return IPCHW_PADMUX_NO_TABLE;

    const muxctrl_reg_t *reg =
        hisi_pad_reg(pad, &gpio_name, &gpio_pad, &gpio_func);
    if (reg == NULL)
        return IPCHW_PADMUX_NO_PAD;

    uint32_t val;
    if (!io->read(reg->address, &val, 32))
        return IPCHW_PADMUX_IO;

    const uint32_t mask = padmux_func_mask();
    uint32_t sel = val & mask;

    /* A selector past the end of the list, or one pointing at a hole. Both
     * mean this build cannot name what the pad is doing, which is a different
     * answer from "it is doing nothing". */
    int i;
    for (i = 0; reg->funcs[i]; i++)
        if ((uint32_t)i == sel)
            break;
    if (reg->funcs[i] == 0 || !strcmp(row_name(reg, i), "reserved"))
        return 0;

    *out = (ipchw_padmux_t){
        .address = reg->address,
        .func_mask = mask,
        .func = (int)sel,
        .func_name = row_name(reg, i),
        .gpio_name = gpio_name,
        .gpio_pad = gpio_pad,
        .gpio_func = gpio_func,
        .flags = IPCHW_PADMUX_F_RMW | IPCHW_PADMUX_F_SHARED_REG |
                 ((int)sel == gpio_func ? IPCHW_PADMUX_F_GPIO : 0),
    };

    return 1;
}

static int hisi_set(int pad, const char *func_name, const padmux_io_t *io) {
    const char *gpio_name;
    int gpio_pad, gpio_func;

    if (regs_by_chip() == NULL)
        return IPCHW_PADMUX_NO_TABLE;

    const muxctrl_reg_t *reg =
        hisi_pad_reg(pad, &gpio_name, &gpio_pad, &gpio_func);
    if (reg == NULL)
        return IPCHW_PADMUX_NO_PAD;

    int want = -1;
    if (!strcmp(func_name, IPCHW_PADMUX_GPIO)) {
        want = gpio_func;
    } else {
        for (int i = 0; reg->funcs[i]; i++) {
            /* "reserved" is a hole in the selector, not a function. The walk
             * and the read both treat it as unnamed; resolving it here would
             * let ipchw_padmux_set(pad, "reserved") put a pad into a state
             * the part does not define. */
            if (!strcmp(row_name(reg, i), "reserved"))
                continue;
            if (!strcmp(row_name(reg, i), func_name)) {
                want = i;
                break;
            }
        }
    }
    if (want < 0)
        return IPCHW_PADMUX_NO_FUNC;

    uint32_t val;
    if (!io->read(reg->address, &val, 32))
        return IPCHW_PADMUX_IO;

    /* Only the selector field moves. The rest of the register carries the
     * drive strength, pull and slew the boot chose. */
    const uint32_t mask = padmux_func_mask();
    val = (val & ~mask) | ((uint32_t)want & mask);
    if (!io->write(reg->address, val, 32))
        return IPCHW_PADMUX_IO;

    return 0;
}

const padmux_ops_t PADMUX_OPS_HISI = {
    .name = "hisi",
    .walk = hisi_walk,
    .get = hisi_get,
    .set = hisi_set,
};

bool parse_gpio_level(const char *arg, unsigned *level) {
    char *tail;
    errno = 0;
    unsigned long val = strtoul(arg, &tail, 10);
    if (errno || tail == arg || *tail || val > 1)
        return false;
    *level = (unsigned)val;
    return true;
}

uint32_t gpio_windows_in_mapping(unsigned long off, unsigned long len,
                                 uint32_t base, uint32_t stride, int nwin) {
    uint32_t mask = 0;
    for (int i = 0; i < nwin && i < 32; i++) {
        uint32_t lo = base + (uint32_t)i * stride;
        uint32_t hi = lo + stride;
        if (off < hi && off + len > lo)
            mask |= 1u << i;
    }
    return mask;
}

/* Everything below is the command-line half of ipctool: it prints, it parses
 * argv, and it calls print_usage() out of main.c. STANDALONE_LIBRARY builds
 * (libipchw) take the tables and the lookups above and stop here. */
#ifndef STANDALONE_LIBRARY

#ifdef IPCHW_VENDOR_INGENIC
#include "hal/ingenic_reginfo.h"
#endif
#ifdef IPCHW_VENDOR_SSTAR
#include "hal/sstar_reginfo.h"
#endif

static int gpio_mux_by(const char *gpio_number, int func_num,
                       const char *set_func);
static int padmux_refuse(int code, const char *pad_spec, const char *func);
static int sstar_gpio_getset(char **argv, bool set_op);
static int sstar_gpio_scan_cmd(void);
static char *sstar_gpio_possible_ircut(char *outbuf, size_t outlen);

static void show_function(const uint16_t *func, unsigned val) {
    for (size_t i = 0; func[i]; i++)
        printf(i == val ? " [%s]" : " %s", padmux_name(func[i]));
    puts("");
}

/* What `reginfo` dumps. On HiSilicon and Goke it is the pad-mux table itself.
 * On SigmaStar and Ingenic it is the GPIO controller's own registers, which is
 * what those two lists have always been -- per-pad direction and level on one,
 * the port INT/MSK/PAT/pull/drive registers on the other. Useful, and not
 * pin-mux: `reginfo --pads` is the pin-mux view on every family. */
static const muxctrl_reg_t **dump_regs_by_chip(void) {
    switch (chip_generation) {
#ifdef IPCHW_VENDOR_SSTAR
    case INFINITY6:
    case INFINITY6B:
        return I6B_regs;
    case INFINITY6C:
        return I6C_regs;
    case INFINITY6E:
        return I6E_regs;
#endif
#ifdef IPCHW_VENDOR_INGENIC
    case T21:
        return T21_regs; /* six ports */
    case T40:
        return T40_regs; /* four */
    case T23:
    case T31:
        /* Three, and the list these two have always dumped. */
        return T31_regs;
#endif
    default:
        break;
    }

    const muxctrl_reg_t **regs = regs_by_chip();
    if (regs == NULL) {
        fprintf(stderr, "Platform is not supported\n");
        exit(EXIT_FAILURE);
    }
    return regs;
}

/* The field of a dumped register worth bracketing a name against. Only the
 * HiSilicon dump is a selector at all; the other two print the whole port. */
static uint32_t dump_mask(void) {
    switch (chip_generation) {
    case INFINITY6:
    case INFINITY6B:
    case INFINITY6C:
    case INFINITY6E:
        return 0xffff;
    case T21:
    case T23:
    case T31:
    case T40:
        /* Not a selector at all: these are whole 32-bit controller registers
         * and every bit of them is worth printing. */
        return 0xffffffff;
    default:
        return padmux_func_mask();
    }
}

static int dump_regs(bool script_mode) {
    const muxctrl_reg_t **regs = dump_regs_by_chip();

    for (int reg_num = 0; regs[reg_num]; reg_num++) {
        uint32_t val;
        if (!mem_reg(regs[reg_num]->address, &val, OP_READ)) {
            printf("read reg %#x error\n", regs[reg_num]->address);
            continue;
        }

        if (script_mode) {
            printf("devmem %#x 32 %#x\n", regs[reg_num]->address, val);
            continue;
        }

        val &= dump_mask();

        printf("muxctrl_reg%d %#x %#x", reg_num, regs[reg_num]->address, val);
        show_function(regs[reg_num]->funcs, val);
    }

    return EXIT_SUCCESS;
}

/* `ipctool reginfo --pads`: one line per pad, what it is carrying and what
 * else it could carry.
 *
 * The register dump above is per-register and per-vendor; this is per-pad and
 * is the same question on every SoC, which is what makes it the thing to run
 * on a board of a family whose table has just been entered. */
static int dump_pads(void) {
    int n = ipchw_padmux_by_prefix("", NULL, 0);
    if (n < 0)
        return padmux_refuse(n, "this SoC", NULL);
    if (n == 0)
        return EXIT_SUCCESS;

    ipchw_padmux_t *rows = calloc((size_t)n, sizeof(*rows));
    if (rows == NULL) {
        fprintf(stderr, "out of memory\n");
        return EXIT_FAILURE;
    }
    n = ipchw_padmux_by_prefix("", rows, n);

    for (int i = 0; i < n;) {
        int pad = rows[i].gpio_pad;
        int j = i;
        while (j < n && rows[j].gpio_pad == pad)
            j++;
        if (pad < 0) {
            i = j;
            continue;
        }

        ipchw_padmux_t now;
        int res = ipchw_padmux_get(pad, &now);
        const char *carrying = res == 1   ? now.func_name
                               : res == 0 ? "?"
                                          : "unreadable";

        printf("pad %-4d %-16s [%s]", pad,
               rows[i].gpio_name ? rows[i].gpio_name : "-", carrying);
        for (int k = i; k < j; k++)
            if (strcmp(rows[k].func_name, carrying) != 0)
                printf(" %s", rows[k].func_name);
        puts("");

        i = j;
    }

    free(rows);
    return EXIT_SUCCESS;
}

extern void print_usage();

int reginfo_cmd(int argc, char **argv) {
    const struct option long_options[] = {
        {"script", no_argument, NULL, 's'},
        {"pads", no_argument, NULL, 'p'},
        {NULL, 0, NULL, 0},
    };
    bool script_mode = false;
    bool pad_mode = false;
    int res;
    int option_index;

    while ((res = getopt_long_only(argc, argv, "sp", long_options,
                                   &option_index)) != -1) {
        switch (res) {
        case 's':
            script_mode = true;
            break;
        case 'p':
            pad_mode = true;
            break;
        case '?':
            print_usage();
            return EXIT_FAILURE;
        }
    }

    getchipname();

    if (pad_mode)
        return dump_pads();

    return dump_regs(script_mode);
}

static void print_bin(size_t data, size_t enabled) {
    for (int i = 7; i >= 0; i--) {
        if (!(enabled >> i & 1))
            printf("x");
        else if (data >> i & 1)
            printf("1");
        else
            printf("0");
    }
}

static void print_line(unsigned int cnt) {
    char buffer[cnt + 1];
    memset(buffer, '=', cnt);
    buffer[cnt] = '\0';
    printf("%s\n", buffer);
}

static bool get_chip_gpio_adress(size_t *GPIO_Base, size_t *GPIO_Offset,
                                 int *GPIO_Groups) {
    *GPIO_Offset = 0x10000;

    switch (chip_generation) {
    case HISI_V1:
        *GPIO_Base = 0x20140000;
        *GPIO_Groups = 12;
        break;
    case HISI_V2A:
        *GPIO_Base = 0x20140000;
        *GPIO_Groups = IS_CHIP("3516AV100") ? 17 : 15;
        break;
    case HISI_V2:
        *GPIO_Base = 0x20140000;
        *GPIO_Groups = 9;
        break;
    case HISI_V3A:
        *GPIO_Base = 0x12140000;
        *GPIO_Groups = 16;
        *GPIO_Offset = 0x1000;
        break;
    case HISI_V3:
        *GPIO_Base = 0x12140000;
        *GPIO_Groups = 9;
        *GPIO_Offset = 0x1000;
        break;
    case HISI_V4A:
        // AV300
        *GPIO_Base = 0x120D0000;
        *GPIO_Groups = 12;
        *GPIO_Offset = 0x1000;
        break;
    case HISI_OT:
        // CV610
        *GPIO_Base = 0x11090000;
        *GPIO_Groups = 11;
        *GPIO_Offset = 0x1000;
        break;
    case HISI_V4:
        *GPIO_Base = 0x120B0000;
        *GPIO_Groups = IS_16EV300 || IS_16DV200 ? 10 : 9;
        *GPIO_Offset = 0x1000;
        break;
    case HISI_3536C:
        *GPIO_Base = 0x12150000;
        *GPIO_Groups = 14;
        break;
    case HISI_3536D:
        *GPIO_Base = 0x12150000;
        *GPIO_Groups = 6;
        break;
    default:
        return false;
    }
    return true;
}

static int gpio_manipulate(char **argv, bool set_op) {
    int GPIO_Groups = 0;
    size_t GPIO_Base = 0;
    size_t GPIO_Offset = 0;

    getchipname();
    if (sstar_gpio_supported())
        return sstar_gpio_getset(argv, set_op);
    if (!get_chip_gpio_adress(&GPIO_Base, &GPIO_Offset, &GPIO_Groups)) {
        fprintf(stderr, "Chip is not supported\n");
        return EXIT_FAILURE;
    }

    const char *gpio_num = argv[1];
    gpio_mux_by(gpio_num, -1, NULL);

    int group, num;
    if (sscanf(gpio_num, "%d_%d", &group, &num) != 2) {
        num = strtoul(gpio_num, NULL, 10);
        group = num / 8;
        num %= 8;
    }
    if (group > GPIO_Groups || num > 7)
        return EXIT_FAILURE;

    size_t mask = 1 << (2 + num);
    uint32_t val, address = GPIO_Base + (group * GPIO_Offset) + mask;

    if (set_op) {
        /* Refused before any register is touched: the old parse made
         * `gpio set 12 foo` into a real drive-low. */
        unsigned level;
        if (!parse_gpio_level(argv[2], &level)) {
            fprintf(stderr, "Level '%s' is not 0 or 1\n", argv[2]);
            return EXIT_FAILURE;
        }

        size_t daddress = GPIO_Base + (group * GPIO_Offset) + 0x400;
        uint32_t direct;
        if (!mem_reg(daddress, &direct, OP_READ)) {
            fprintf(stderr, "read reg %#x error\n", address);
            return EXIT_FAILURE;
        }
        if (((direct >> num) & 1U) == 0) {
            // If current state is input, set bit it make it output
            direct |= 1UL << num;
            if (!mem_reg(daddress, &direct, OP_WRITE)) {
                fprintf(stderr, "write reg %#x error\n", address);
                return EXIT_FAILURE;
            }
        }

        uint32_t cmd = level << num;
        if (!mem_reg(address, &cmd, OP_WRITE)) {
            printf("write reg %#x error\n", address);
            return EXIT_FAILURE;
        }
    } else {
        if (!mem_reg(address, &val, OP_READ)) {
            printf("read reg %#x error\n", address);
            return EXIT_FAILURE;
        }
        printf("%d\n", val ? 1 : 0);
    }

    return EXIT_SUCCESS;
}

static int gpio_get_cmd(int argc, char **argv) {
    if (argc != 2) {
        printf("Usage: ipctool gpio %s <gpio number>%s\n%s", "get", "",
               "where: <gpio number> either number in 5_6 or 46 format\n");
        return EXIT_FAILURE;
    }

    return gpio_manipulate(argv, false);
}

static int gpio_set_cmd(int argc, char **argv) {
    if (argc != 3) {
        printf("Usage: ipctool gpio %s <gpio number>%s\n%s", "set", " <value>",
               "where: <gpio number> either number in 5_6 or 46 format\n");
        return EXIT_FAILURE;
    }

    return gpio_manipulate(argv, true);
}

/* One place to turn a refusal from the library into the message the command
 * line has always printed. A missing table stays fatal here: the CLI has
 * always treated it that way, and only the library needs the softer answer. */
static int padmux_refuse(int code, const char *pad_spec, const char *func) {
    switch (code) {
    case IPCHW_PADMUX_NO_CHIP:
    case IPCHW_PADMUX_NO_TABLE:
        fprintf(stderr, "Platform is not supported\n");
        exit(EXIT_FAILURE);
    case IPCHW_PADMUX_NO_PAD:
        fprintf(stderr, "GPIO %s is not found\n", pad_spec);
        break;
    case IPCHW_PADMUX_NO_FUNC:
        fprintf(stderr, "GPIO %s cannot carry %s\n", pad_spec,
                func ? func : "that");
        break;
    case IPCHW_PADMUX_IO:
        fprintf(stderr, "Cannot reach the pad-mux register of GPIO %s\n",
                pad_spec);
        break;
    default:
        fprintf(stderr, "Pad-mux error %d on GPIO %s\n", code, pad_spec);
        break;
    }

    return EXIT_FAILURE;
}

/* `ipctool gpio mux <pad> [<function>|<selector>]`, and the implicit "put it
 * back to GPIO" that `gpio get` and `gpio set` do first.
 *
 * The write is ipchw_padmux_set() rather than a read-modify-write composed
 * here, so this command means the same thing on a vendor where the write is
 * not one register. The numeric form still works: a selector value is
 * resolved to the name of the function it selects, which is the only spelling
 * the two other vendors have. */
static int gpio_mux_by(const char *gpio_number, int func_num,
                       const char *set_func) {
    int pad = padmux_parse_pad(gpio_number);
    if (pad < 0) {
        fprintf(stderr, "Not a GPIO number: %s\n", gpio_number);
        return EXIT_FAILURE;
    }

    getchipname();

    const char *want = set_func;
    if (func_num >= 0) {
        ipchw_padmux_t rows[64];
        int n = ipchw_padmux_by_pad(pad, rows, ARRCNT(rows));
        if (n < 0)
            return padmux_refuse(n, gpio_number, set_func);
        if (n > (int)ARRCNT(rows))
            n = (int)ARRCNT(rows);

        /* A selector value is not a name, and outside HiSilicon it is not
         * even unique to a function: a SigmaStar `func` is a value in place,
         * so two peripherals whose fields sit at different offsets of
         * different registers can both select on 0x40 -- SPI1_MODE_4 and
         * TTL_MODE_1 do, on PAD_GPIO0. Take the number only when one
         * function answers to it, and say so when several do rather than
         * muxing the first one found.
         *
         * IPCHW_PADMUX_F_RMW is deliberately NOT required here: an Ingenic
         * row never carries it, because putting a function on the pad is four
         * staged writes rather than one -- but the selector is still a
         * perfectly good name for which function is meant, and
         * ipchw_padmux_set() knows how to write it. */
        want = NULL;
        for (int i = 0; i < n; i++) {
            if (rows[i].func != func_num)
                continue;
            if (want != NULL && strcmp(want, rows[i].func_name) != 0) {
                fprintf(stderr,
                        "GPIO %s: selector %d selects both %s and %s here; "
                        "name the one you mean\n",
                        gpio_number, func_num, want, rows[i].func_name);
                return EXIT_FAILURE;
            }
            want = rows[i].func_name;
        }
        if (want == NULL) {
            fprintf(stderr, "GPIO %s has no function %d\n", gpio_number,
                    func_num);
            return EXIT_FAILURE;
        }
    } else if (want == NULL) {
        /* No function named: say what the pad is carrying. This used to mux
         * the pad to GPIO instead -- `new_func = i`, the pad's own GPIO
         * index, when neither a name nor a number was given -- which made a
         * command that reads like a question perform a write. There was no
         * way to ask at all, and the mistake is silent: running it on an
         * SSC30KQ's PAD_ETH_LED0 dropped LED0_MODE_1 and left the link LED
         * dark until the mode was put back. "Set this pad to GPIO" still has
         * a spelling, and it is the unambiguous one: `gpio mux <pad> GPIO`. */
        ipchw_padmux_t now;
        int res = ipchw_padmux_get(pad, &now);
        if (res < 0)
            return padmux_refuse(res, gpio_number, NULL);

        ipchw_padmux_t rows[64];
        int n = ipchw_padmux_by_pad(pad, rows, ARRCNT(rows));
        if (n < 0)
            return padmux_refuse(n, gpio_number, NULL);
        if (n > (int)ARRCNT(rows))
            n = (int)ARRCNT(rows);

        const char *carrying = res == 1 ? now.func_name : "?";
        const char *name = n > 0 && rows[0].gpio_name ? rows[0].gpio_name : "-";

        printf("pad %-4d %-16s [%s]", pad, name, carrying);
        for (int i = 0; i < n; i++)
            if (strcmp(rows[i].func_name, carrying) != 0)
                printf(" %s", rows[i].func_name);
        puts("");
        return EXIT_SUCCESS;
    }

    int res = ipchw_padmux_set(pad, want);
    if (res != 0)
        return padmux_refuse(res, gpio_number, want);

    return EXIT_SUCCESS;
}

static int gpio_mux_cmd(int argc, char **argv) {
    if (argc < 2 || argc > 3) {
        printf("Usage: ipctool gpio %s <gpio number>%s\n%s%s", "mux",
               " [function name or number]",
               "where: <gpio number> either number in 5_6 or 46 format\n",
               "       with no function, reports what the pad carries;\n"
               "       pass GPIO to mux it back to plain GPIO\n");
        return EXIT_FAILURE;
    }

    const char *set_func = NULL;
    int func_num = -1;
    if (argc == 3) {
        set_func = argv[2];
        if (isdigit(set_func[0]))
            func_num = strtoul(set_func, NULL, 10);
    }

    return gpio_mux_by(argv[1], func_num, set_func);
}

/* Which pads are muxed to plain GPIO right now, a bitmask per bank of eight.
 *
 * False when this SoC has no pad table, so a caller can drop the part of its
 * report that needs one instead of taking the whole process down with it. */
static bool fill_enabled_gpios(size_t *enabled, size_t GPIO_Groups) {
    if (ipchw_padmux_by_prefix("", NULL, 0) < 0)
        return false;

    memset(enabled, 0, sizeof(size_t) * GPIO_Groups);
    for (size_t group = 0; group < GPIO_Groups; group++)
        for (int pin = 0; pin < 8; pin++)
            if (padmux_pad_is_gpio((int)(group * 8) + pin))
                enabled[group] |= (size_t)1 << pin;

    return true;
}

/* A GPIO block's registers, found through a daemon's own /dev/mem mappings.
 *
 * One walk answers both vendors' question: HiSilicon asks which of its
 * group-sized windows are visible and gets a mask; SigmaStar asks whether the
 * single window its pads share is visible and reads bit 0. Any process whose
 * /proc name is all digits is visited -- including init, which on a minimal
 * firmware is the streamer. A mapping counts from its full interval: the
 * file offset is its physical address and the vaddr span is its length, so a
 * daemon holding one broad RIU window from well below is mapped here the
 * same as one that mapped the registers exactly. */
static uint32_t dev_mem_windows_marked(uint32_t base, uint32_t stride,
                                       int nwin) {
    uint32_t marked = 0;
    DIR *proc = opendir("/proc");
    if (!proc)
        return 0;

    struct dirent *ent;
    while ((ent = readdir(proc))) {
        /* Every digit-only name is a pid entry; "." and ".." and the
         * non-numeric /proc files fail this test on their first character. */
        if (ent->d_name[strspn(ent->d_name, "0123456789")])
            continue;

        char path[64];
        snprintf(path, sizeof(path), "/proc/%s/maps", ent->d_name);
        FILE *f = fopen(path, "r");
        if (!f)
            continue;

        char line[256];
        unsigned long start, end, off;
        while (fgets(line, sizeof(line), f)) {
            if (!strstr(line, "/dev/mem"))
                continue;
            if (sscanf(line, "%lx-%lx %*s %lx", &start, &end, &off) != 3)
                continue;
            marked |=
                gpio_windows_in_mapping(off, end - start, base, stride, nwin);
        }
        fclose(f);
    }
    closedir(proc);
    return marked;
}

char *gpio_possible_ircut(char *outbuf, size_t outlen) {
    int GPIO_Groups = 0;
    size_t GPIO_Base = 0;
    size_t GPIO_Offset = 0;

    *outbuf = 0;
    if (sstar_gpio_supported())
        return sstar_gpio_possible_ircut(outbuf, outlen);
    if (!get_chip_gpio_adress(&GPIO_Base, &GPIO_Offset, &GPIO_Groups))
        return NULL;

    uint32_t streamer_groups =
        dev_mem_windows_marked(GPIO_Base, GPIO_Offset, GPIO_Groups);

    size_t enabled[GPIO_Groups];
    if (!fill_enabled_gpios(enabled, GPIO_Groups))
        return NULL;

    // Count output pins per group to filter out busy I/O groups
    uint8_t output_count[GPIO_Groups];
    uint8_t dir_cache[GPIO_Groups];
    uint8_t val_cache[GPIO_Groups];
    memset(output_count, 0, sizeof(output_count));

    for (int group = 0; group < GPIO_Groups; group++) {
        size_t mask = enabled[group] << 2;
        size_t address = GPIO_Base + (group * GPIO_Offset) + mask;
        uint32_t value;
        if (!mem_reg(address, &value, OP_READ)) {
            fprintf(stderr, "Error at %#zx\n", address);
            return NULL;
        }
        address = GPIO_Base + (group * GPIO_Offset) + 0x400;
        uint32_t direct;
        if (!mem_reg(address, &direct, OP_READ)) {
            fprintf(stderr, "Error at %#zx\n", address);
            return NULL;
        }
        dir_cache[group] = direct;
        val_cache[group] = value;

        for (int i = 0; i < 8; i++)
            if ((enabled[group] >> i & 1) && (direct & (1 << i)))
                output_count[group]++;
    }

    char *ptr = outbuf;
    for (int group = 0; group < GPIO_Groups; group++) {
        for (int i = 0; i < 8; i++) {
            uint8_t bit_mask = 1 << i;
            if (!(enabled[group] >> i & 1))
                continue;
            if (!(dir_cache[group] & bit_mask))
                continue;

            bool candidate;
            if (streamer_groups)
                // Only report from streamer-mapped groups with few outputs
                // (dedicated IR cut groups typically have 1-2 output pins)
                candidate = (streamer_groups & (1u << group)) &&
                            output_count[group] <= 2;
            else
                candidate = (val_cache[group] & bit_mask) == 0;

            if (candidate) {
                int nlen = snprintf(ptr, outlen, ",%d", group * 8 + i);
                outlen -= nlen;
                ptr += nlen;
            }
        }
    }

    if (strlen(outbuf) > 0)
        return outbuf + 1;
    else
        return NULL;
}

/* Whether a vendor daemon holds this SigmaStar's pad registers through a
 * raw /dev/mem mapping of its own -- the same question the HiSilicon walk
 * asks of its bank words. The pad registers of one chip share a single page,
 * so the answer is one bit for every pad rather than a per-group mask. */
static bool sstar_gpio_streamer_mapped(void) {
    uint32_t base = sstar_gpio_pad_addr(0) & ~0xfffu;
    uint32_t end = sstar_gpio_pad_addr(sstar_gpio_num_pads() - 1) + 4;
    return dev_mem_windows_marked(base, end - base, 1) != 0;
}

/* `gpio get/set <pad>` on SigmaStar: the pad number is a pad, its register is
 * one byte, and there are no bank words and no group_pin syntax. The mux
 * line is printed here, matching where the HiSilicon path prints it. */
static int sstar_gpio_getset(char **argv, bool set_op) {
    const char *gpio_num = argv[1];

    gpio_mux_by(gpio_num, -1, NULL);

    char *tail;
    long pad = strtol(gpio_num, &tail, 10);
    if (tail == gpio_num || *tail || pad < 0 || pad >= sstar_gpio_num_pads()) {
        fprintf(stderr, "GPIO %s is out of range\n", gpio_num);
        return EXIT_FAILURE;
    }

    uint8_t val;
    if (!sstar_gpio_read((int)pad, &val)) {
        fprintf(stderr, "read reg %#x error\n", sstar_gpio_pad_addr((int)pad));
        return EXIT_FAILURE;
    }

    if (set_op) {
        /* Refused before the register changes: the old parse made
         * `gpio set 12 foo` into a real drive-low. */
        unsigned level;
        if (!parse_gpio_level(argv[2], &level)) {
            fprintf(stderr, "Level '%s' is not 0 or 1\n", argv[2]);
            return EXIT_FAILURE;
        }

        if (val & SSTAR_GPIO_BIT_INPUT)
            val &= (uint8_t)~SSTAR_GPIO_BIT_INPUT;
        if (level)
            val |= SSTAR_GPIO_BIT_OUT;
        else
            val &= (uint8_t)~SSTAR_GPIO_BIT_OUT;
        if (!sstar_gpio_write((int)pad, val)) {
            fprintf(stderr, "write reg %#x error\n",
                    sstar_gpio_pad_addr((int)pad));
            return EXIT_FAILURE;
        }
    } else {
        bool is_input = val & SSTAR_GPIO_BIT_INPUT;
        printf("%d\n", is_input ? !!(val & SSTAR_GPIO_BIT_IN)
                                : !!(val & SSTAR_GPIO_BIT_OUT));
    }

    return EXIT_SUCCESS;
}

/* The IR-cut question on SigmaStar: the HiSilicon heuristic walks bank words
 * and keeps the output pins of a lightly-loaded, streamer-held group; the
 * same idea over pads keeps the output pads, pared back the same two ways --
 * to the whole block when a daemon holds it and drives at most two pins, and
 * otherwise to the outputs standing at zero. */
static char *sstar_gpio_possible_ircut(char *outbuf, size_t outlen) {
    int nr_pads = sstar_gpio_num_pads();
    if (!nr_pads || ipchw_padmux_by_prefix("", NULL, 0) < 0)
        return NULL;

    uint8_t levels[nr_pads];
    bool is_gpio[nr_pads];
    memset(levels, 0, sizeof(levels));
    memset(is_gpio, 0, sizeof(is_gpio));

    int output_count = 0;
    for (int pad = 0; pad < nr_pads; pad++) {
        if (!padmux_pad_is_gpio(pad))
            continue;
        uint8_t val;
        if (!sstar_gpio_read(pad, &val)) {
            fprintf(stderr, "Error at %#x\n", sstar_gpio_pad_addr(pad));
            return NULL;
        }
        is_gpio[pad] = true;
        levels[pad] = val;
        if (!(val & SSTAR_GPIO_BIT_INPUT))
            output_count++;
    }

    bool streamer = sstar_gpio_streamer_mapped();
    char *ptr = outbuf;

    for (int pad = 0; pad < nr_pads; pad++) {
        if (!is_gpio[pad])
            continue;
        uint8_t val = levels[pad];
        if (val & SSTAR_GPIO_BIT_INPUT)
            continue;
        if (streamer && output_count > 2)
            continue;
        if (!streamer && (val & SSTAR_GPIO_BIT_OUT))
            continue;

        int nlen = snprintf(ptr, outlen, ",%d", pad);
        outlen -= nlen;
        ptr += nlen;
    }

    if (strlen(outbuf) > 0)
        return outbuf + 1;
    return NULL;
}

/* `gpio scan` on SigmaStar: watch every pad muxed to plain GPIO. The HiSilicon
 * loop prints eight pins of a bank at a time; this one prints one line per
 * pad, and only the three bits a pad register has. */
static int sstar_gpio_scan_cmd(void) {
    int nr_pads = sstar_gpio_num_pads();
    if (!nr_pads || ipchw_padmux_by_prefix("", NULL, 0) < 0) {
        fprintf(stderr, "Platform is not supported\n");
        return EXIT_FAILURE;
    }

    uint8_t state[nr_pads];
    memset(state, 0, sizeof(state));

    for (int pad = 0; pad < nr_pads; pad++) {
        if (!padmux_pad_is_gpio(pad))
            continue;
        uint8_t val;
        if (!sstar_gpio_read(pad, &val)) {
            fprintf(stderr, "Error at %#x\n", sstar_gpio_pad_addr(pad));
            return EXIT_FAILURE;
        }
        state[pad] = val;
        printf("Pad:%2d, Addr:0x%08x, Data:0x%02X = in:%d out:%d oe_n:%d\n",
               pad, sstar_gpio_pad_addr(pad), val, val & 1, (val >> 1) & 1,
               (val >> 2) & 1);
    }

    print_line(86);
    printf("Waiting for while something changes...\n");
    while (1) {
        for (int pad = 0; pad < nr_pads; pad++) {
            if (!padmux_pad_is_gpio(pad))
                continue;
            uint8_t val;
            if (!sstar_gpio_read(pad, &val)) {
                /* A /dev/mem that has stopped reading will not start again;
                 * a blind watcher that retries every 100 ms and names the
                 * same pad each time is worse than stopping. */
                fprintf(stderr, "Error at %#x\n", sstar_gpio_pad_addr(pad));
                return EXIT_FAILURE;
            }
            if (val == state[pad])
                continue;

            bool is_input = val & SSTAR_GPIO_BIT_INPUT;
            printf("Pad:%d, Addr:0x%08x, 0x%02X --> 0x%02X = in:%d out:%d "
                   "oe_n:%d, Dir:%s, Level:%d\n",
                   pad, sstar_gpio_pad_addr(pad), state[pad], val, val & 1,
                   (val >> 1) & 1, (val >> 2) & 1,
                   is_input ? "Input" : "Output",
                   is_input ? (val & SSTAR_GPIO_BIT_IN) != 0
                            : (val & SSTAR_GPIO_BIT_OUT) != 0);
            state[pad] = val;
        }
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

static int gpio_scan_cmd() {
    int GPIO_Groups = 0;
    size_t GPIO_Base = 0;
    size_t GPIO_Offset = 0;

    /* This command is a loop that only ever ends on Ctrl-C, so a block-buffered
     * stdout never gets flushed: `gpio scan > log` or `| tee` captured an empty
     * file, which is precisely what someone recording a pin hunt does. Line
     * buffering costs nothing at ten samples a second. */
    setvbuf(stdout, NULL, _IOLBF, 0);

    getchipname();
    if (sstar_gpio_supported())
        return sstar_gpio_scan_cmd();
    if (!get_chip_gpio_adress(&GPIO_Base, &GPIO_Offset, &GPIO_Groups))
        return EXIT_FAILURE;

    size_t state[GPIO_Groups];
    size_t enabled[GPIO_Groups];
    if (!fill_enabled_gpios(enabled, GPIO_Groups)) {
        fprintf(stderr, "Platform is not supported\n");
        return EXIT_FAILURE;
    }

    for (int group = 0; group < GPIO_Groups; group++) {
        size_t mask = enabled[group] << 2;
        size_t address = GPIO_Base + (group * GPIO_Offset) + mask;
        uint32_t value;
        if (!mem_reg(address, &value, OP_READ)) {
            fprintf(stderr, "Error at %#zx\n", address);
            return EXIT_FAILURE;
        }
        state[group] = value;
        printf("Gr:%2d, Addr:0x%08zX, Data:0x%02X = 0b", group, address, value);
        print_bin(value, enabled[group]);
        address = GPIO_Base + (group * GPIO_Offset) + 0x400;
        uint32_t direct;
        if (!mem_reg(address, &direct, OP_READ)) {
            fprintf(stderr, "Error at %#zx\n", address);
            return EXIT_FAILURE;
        }
        printf(", Addr:0x%08zX, Dir:0x%02X = 0b", address, direct);
        print_bin(direct, enabled[group]);
        printf("\n");
    }

    print_line(86);
    printf("Waiting for while something changes...\n");
    while (1) {
        for (int group = 0; group < GPIO_Groups; group++) {
            size_t mask = enabled[group] << 2;
            size_t address = GPIO_Base + (group * GPIO_Offset) + mask;
            uint32_t value;
            if (!mem_reg(address, &value, OP_READ)) {
                /* A /dev/mem that has stopped reading will not start again;
                 * a blind watcher that retries every 100 ms and names the
                 * same register each time is worse than stopping. */
                fprintf(stderr, "Error at %#zx\n", address);
                return EXIT_FAILURE;
            }
            if (state[group] != value) {
                bool HeaderByte = false;
                for (int bit = 7; bit >= 0; bit--) {
                    int old_bit = (state[group] >> bit) & 1;
                    int new_bit = (value >> bit) & 1;
                    if (old_bit != new_bit) {
                        if (HeaderByte == false) {
                            print_line(86);
                            printf("Gr:%d, Addr:0x%08zX, Data:0x%02zX = 0b",
                                   group, address, state[group]);
                            print_bin(state[group], enabled[group]);
                            printf(" --> 0x%02X = 0b", value);
                            print_bin(value, enabled[group]);
                            printf("\n");
                            HeaderByte = true;
                        }
                        address = GPIO_Base + (group * GPIO_Offset) + 0x400;
                        uint32_t direct;
                        if (!mem_reg(address, &direct, OP_READ)) {
                            fprintf(stderr, "Error at %#zx\n", address);
                            break;
                        }
                        direct = (direct >> bit) & 1;
                        address = GPIO_Base + (group * GPIO_Offset) +
                                  (1 << (bit + 2));
                        int mask = value & 1 << bit;
                        printf("Mask: \"devmem 0x%08zX 32 0x%02X\", "
                               "GPIO%d_%d, GPIO%d, "
                               "Dir:%s, Level:%d\n",
                               address, mask, group, bit, (group * 8) + bit,
                               direct ? "Output" : "Input", new_bit);
                    }
                }
                state[group] = value;
            }
        }
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

int gpio_cmd(int argc, char **argv) {
    if (argc > 1) {
        if (!strcmp(argv[1], "scan"))
            return gpio_scan_cmd();
        else if (!strcmp(argv[1], "mux"))
            return gpio_mux_cmd(argc - 1, argv + 1);
        else if (!strcmp(argv[1], "get"))
            return gpio_get_cmd(argc - 1, argv + 1);
        else if (!strcmp(argv[1], "set"))
            return gpio_set_cmd(argc - 1, argv + 1);
    }

    printf("Usage: ipctool gpio <command>\n");
    return EXIT_FAILURE;
}

#endif /* !STANDALONE_LIBRARY */
